-- Dev schedule template: standard 9am-5pm workday for dev provider 999998
-- 96 slots of 15 min: 36 closed (midnight-9am) + 32 open (9am-5pm) + 28 closed (5pm-midnight)

-- Generate weekday schedule dates for dev provider 999998 (2025-01-01 through 2027-12-31)
-- This allows FindNextAvailableSlot to find open slots in the dev environment
DROP PROCEDURE IF EXISTS `dev_gen_schedule_dates`;
DELIMITER //
CREATE PROCEDURE `dev_gen_schedule_dates`()
BEGIN
  DECLARE d DATE DEFAULT '2025-01-01';
  WHILE d <= '2027-12-31' DO
    IF DAYOFWEEK(d) NOT IN (1, 7) THEN
        VALUES (d,'999998','Y','1','','Standard','admin','A');
    END IF;
    SET d = DATE_ADD(d, INTERVAL 1 DAY);
  END WHILE;
END //
DELIMITER ;
CALL `dev_gen_schedule_dates`();
DROP PROCEDURE IF EXISTS `dev_gen_schedule_dates`;

